body.script:
document.querySelectorAll('.project-card[data-href]').forEach((card) => {
  card.addEventListener('click', (e) => {
    if (e.target.closest('a, button')) return;
    window.location.href = card.getAttribute('data-href');
  });
});

document.querySelectorAll('.copy-btn').forEach((btn) => {
  const originalText = btn.textContent.trim();
  const email = btn.getAttribute('data-email');
  btn.addEventListener('click', () => {
    if (navigator.clipboard) {
      navigator.clipboard.writeText(email).then(() => {
        btn.textContent = `✓ 已复制 ${email}`;
        setTimeout(() => { btn.textContent = originalText; }, 2200);
      });
    } else {
      window.location.href = `mailto:${email}`;
    }
  });
});

    const cases = {
      led: {
        file: 'OUTPUT: led-indicator-5v.eprj3',
        status: 'engineering_preview',
        ok: true,
        svg: `
          +5V


          R1 330Ω



          LED1

          GND
        `,
        bundle: `{\n  "template": "led_indicator_5v",\n  "deliveryLevel": "engineering_preview",\n  "artifacts": [".eprj3", "BOM.csv", "VerificationBundle.json"],\n  "reproChecks": "6/6 basic pipeline steps · LCEDA V4.1+ openable"\n}`
      },
      rc: {
        file: 'OUTPUT: rc-lowpass-filter.eprj3',
        status: 'engineering_preview',
        ok: true,
        svg: `
          VIN


          R1 10kΩ

          VOUT




          C1 100nF

          GND
        `,
        bundle: `{\n  "template": "rc_lowpass_filter",\n  "deliveryLevel": "engineering_preview",\n  "artifacts": [".eprj3", "BOM.csv", "VerificationBundle.json"],\n  "knownGap": "不生成 Gerber/CPL；Netlist 审计仍含已知问题"\n}`
      },
      reject: {
        file: 'RESULT: REJECTED_OUT_OF_SCOPE',
        status: 'explicit_reject',
        ok: false,
        svg: `


⛔ 明确拒绝生成占位工程

请求「ESP32-S3 + BME280 整板」超出当前受限规则模板范围，
系统按契约拒绝输出，确保不交付伪造/不可用工程包。
        `,
        bundle: `{\n  "accepted": false,\n  "reason": "UNSUPPORTED_HARDWARE_SCOPE",\n  "supportedTemplates": ["led_indicator_5v", "rc_lowpass_filter"],\n  "placeholderGenerated": false\n}`
      }
    };

    function renderCase(key) {
      const c = cases[key];
      document.getElementById('stageFile').textContent = c.file;
      const st = document.getElementById('stageStatus');
      st.textContent = c.status;
      st.className = 'status-tag ' + (c.ok ? 'st-ok' : 'st-rej');
      document.getElementById('svgWrap').innerHTML = c.svg;
      document.getElementById('bundleOut').textContent = c.bundle;
    }
    renderCase('led');

    document.querySelectorAll('.case-btn').forEach((btn) => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.case-btn').forEach((b) => b.classList.remove('active'));
        btn.classList.add('active');
        renderCase(btn.getAttribute('data-case'));
      });
    });

const scenes = {
