document.querySelectorAll('.scene-btn').forEach((btn) => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.scene-btn').forEach((b) => b.classList.remove('active'));
    btn.classList.add('active');
    const s = scenes[btn.getAttribute('data-scene')];
    document.getElementById('vPocket').textContent = s.pocket;
    document.getElementById('vSaving').textContent = s.saving;
    document.getElementById('txBanner').innerHTML = s.tx;
    document.getElementById('aiTip').innerHTML = s.ai;
  });
});

// 点击项目卡片空白区域即可跳转对应展示页
document.querySelectorAll('.project-card[data-href]').forEach((card) => {
  card.addEventListener('click', (e) => {
    if (e.target.closest('a, button')) return;
    const url = card.getAttribute('data-href');
    if (card.getAttribute('data-external') === 'true') {
      window.open(url, '_blank', 'noopener');
    } else {
      window.location.href = url;
    }
  });
});

// 双邮箱一键复制
document.querySelectorAll('.copy-btn').forEach((btn) => {
  const originalText = btn.textContent.trim();
  const email = btn.getAttribute('data-email');
  btn.addEventListener('click', () => {
    if (navigator.clipboard) {
      navigator.clipboard.writeText(email).then(() => {
        btn.textContent = `✓ 已复制 ${email}`;
        setTimeout(() => { btn.textContent = originalText; }, 2200);
      });
    } else {
      window.location.href = `mailto:${email}`;
    }
  });
});
